import { defineProjector } from '../projections/projection-runner.mjs';
import { SOCIAL_EVENT_TYPES, normalizeCommentPayload, normalizeDecisionPayload, normalizeEngagementPayload, normalizeGraphPayload, normalizePersonaPayload, normalizePostPayload } from './social-event-types.mjs';
import { socialPostHeadId } from './post.mjs';
import { socialCommentHeadId } from './comment.mjs';

export const SOCIAL_PROJECTOR_ID = 'tmrw-social-v1';
const MAX_SEQUENCE = Number.MAX_SAFE_INTEGER;
function project(event) {
  if (event.eventType === SOCIAL_EVENT_TYPES.PERSONA_STATE) { const { persona } = normalizePersonaPayload(event.payload); return [{ kind: 'social-persona-source', projectionKey: `persona:${persona.personaId}`, groupKey: `persona:${persona.personaId}`, data: { persona } }]; }
  if (event.eventType === SOCIAL_EVENT_TYPES.GRAPH_STATE) { const { edge } = normalizeGraphPayload(event.payload); return [{ kind: 'social-graph-source', projectionKey: `graph:${edge.edgeId}`, groupKey: `graph:${edge.edgeId}`, data: { edge } }]; }
  if (event.eventType === SOCIAL_EVENT_TYPES.POST_CREATED) { const { post } = normalizePostPayload(event.payload); return [{ kind: 'social-post-source', projectionKey: `post:${post.postId}`, groupKey: `post:${post.postId}`, data: { post } }, ...post.audience.recipientAccountIds.map(accountId => ({ kind: 'social-post-recipient-source', projectionKey: `post-recipient:${post.postId}:${accountId}`, groupKey: `post-recipient:${post.postId}:${accountId}`, data: { postId: post.postId, recipientAccountId: accountId } }))]; }
  if (event.eventType === SOCIAL_EVENT_TYPES.COMMENT_CREATED) { const { comment, recipientAccountIds } = normalizeCommentPayload(event.payload); return [{ kind: 'social-comment-source', projectionKey: `comment:${comment.commentId}`, groupKey: `comment:${comment.commentId}`, data: { comment } }, ...recipientAccountIds.map(accountId => ({ kind: 'social-comment-recipient-source', projectionKey: `comment-recipient:${comment.commentId}:${accountId}`, groupKey: `comment-recipient:${comment.commentId}:${accountId}`, data: { commentId: comment.commentId, accountId } }))]; }
  if (event.eventType === SOCIAL_EVENT_TYPES.ENGAGEMENT_STATE) { const { engagement } = normalizeEngagementPayload(event.payload); return [{ kind: 'social-engagement-source', projectionKey: `engagement:${engagement.engagementId}`, groupKey: `engagement:${engagement.engagementId}`, data: { engagement } }]; }
  if (event.eventType === SOCIAL_EVENT_TYPES.DECISION_RECORDED) { const { decision } = normalizeDecisionPayload(event.payload); return [{ kind: 'social-decision-source', projectionKey: `decision:${decision.triggerEventId}:${decision.actorInstanceId}`, groupKey: `decision:${decision.triggerEventId}:${decision.actorInstanceId}`, data: { decision } }]; }
  return [];
}
async function rows(repositories, scope, groupKey) { return repositories.projections.listByIndexRange('by_scope_projector_group_sequence', { lower: [scope.storyId, scope.branchId, SOCIAL_PROJECTOR_ID, groupKey, 0], upper: [scope.storyId, scope.branchId, SOCIAL_PROJECTOR_ID, groupKey, MAX_SEQUENCE] }); }
const newest = source => [...source].sort((a, b) => a.sourceEventSequence - b.sourceEventSequence || a.id.localeCompare(b.id)).at(-1) || null;
async function materialize(repositories, scope, groupKey, updatedAt) {
  const sourceRows = await rows(repositories, scope, groupKey); const row = newest(sourceRows);
  if (groupKey.startsWith('persona:')) { const id = groupKey.slice(8); if (!row) await repositories.socialPersonas.delete(id); else { const persona = row.data.persona; const personaKey = persona.sourceLevel === 'actor-base' ? `actor:${persona.actorId}` : `instance:${persona.instanceId}`; await repositories.socialPersonas.put(Object.freeze({ id, storyId: scope.storyId, branchId: scope.branchId, ...persona, personaKey, sourceEventId: row.sourceEventId, sourceEventRevision: row.sourceEventRevision, updatedAt, phase: 15 })); } }
  else if (groupKey.startsWith('graph:')) { const id = groupKey.slice(6); if (!row) await repositories.socialGraphEdges.delete(id); else await repositories.socialGraphEdges.put(Object.freeze({ id, storyId: scope.storyId, branchId: scope.branchId, ...row.data.edge, activeState: row.data.edge.active ? 'active' : 'inactive', sourceEventId: row.sourceEventId, sourceEventRevision: row.sourceEventRevision, updatedAt, phase: 15 })); }
  else if (groupKey.startsWith('post-recipient:')) { const data = row?.data; const id = data ? `social-post-recipient:${scope.storyId}:${scope.branchId}:${data.postId}:${data.recipientAccountId}` : null; if (id && row) await repositories.socialPostRecipients.put(Object.freeze({ id, storyId: scope.storyId, branchId: scope.branchId, ...data, reverseSequence: MAX_SEQUENCE - row.sourceEventSequence, sourceEventId: row.sourceEventId, updatedAt, phase: 15 })); }
  else if (groupKey.startsWith('post:')) { const postId = groupKey.slice(5); const id = socialPostHeadId(scope, postId); if (!row) await repositories.socialPosts.delete(id); else await repositories.socialPosts.put(Object.freeze({ id, storyId: scope.storyId, branchId: scope.branchId, ...row.data.post, audienceKind: row.data.post.audience.kind, current: true, currentState: 'current', sourceEventId: row.sourceEventId, sourceEventRevision: row.sourceEventRevision, sourceEventSequence: row.sourceEventSequence, reverseSequence: MAX_SEQUENCE - row.sourceEventSequence, updatedAt, phase: 15 })); }
  else if (groupKey.startsWith('comment:')) { const commentId = groupKey.slice(8); const id = socialCommentHeadId(scope, commentId); if (!row) await repositories.socialComments.delete(id); else await repositories.socialComments.put(Object.freeze({ id, storyId: scope.storyId, branchId: scope.branchId, ...row.data.comment, parentKey: row.data.comment.parentCommentId || 'root', sourceEventId: row.sourceEventId, sourceEventRevision: row.sourceEventRevision, sourceEventSequence: row.sourceEventSequence, updatedAt, phase: 15 })); }
  else if (groupKey.startsWith('engagement:')) { const id = groupKey.slice(11); if (!row) await repositories.socialEngagements.delete(id); else await repositories.socialEngagements.put(Object.freeze({ id, storyId: scope.storyId, branchId: scope.branchId, ...row.data.engagement, activeState: row.data.engagement.active ? 'active' : 'inactive', sourceEventId: row.sourceEventId, sourceEventRevision: row.sourceEventRevision, updatedAt, phase: 15 })); }
  else if (groupKey.startsWith('decision:')) { const data = row?.data.decision; const id = data ? `social-decision:${scope.storyId}:${scope.branchId}:${data.triggerEventId}:${data.actorInstanceId}` : groupKey; if (!row) await repositories.socialDecisions.delete(id); else await repositories.socialDecisions.put(Object.freeze({ id, storyId: scope.storyId, branchId: scope.branchId, ...data, sourceEventId: row.sourceEventId, updatedAt, phase: 15 })); }
  return { sourceRowsRead: sourceRows.length, rowsWritten: row ? 1 : 0 };
}
async function applyAggregate({ repositories, scope, previousRows, currentRows, updatedAt }) { let sourceRowsRead = 0; let rowsWritten = 0; for (const key of new Set([...previousRows, ...currentRows].map(row => row.groupKey).filter(Boolean))) { const prior = previousRows.find(row => row.groupKey === key)?.data; const current = currentRows.find(row => row.groupKey === key); if (!current && key.startsWith('post-recipient:') && prior) await repositories.socialPostRecipients.delete(`social-post-recipient:${scope.storyId}:${scope.branchId}:${prior.postId}:${prior.recipientAccountId}`); const result = await materialize(repositories, scope, key, updatedAt); sourceRowsRead += result.sourceRowsRead; rowsWritten += result.rowsWritten; } return { sourceRowsRead, rowsWritten, eventHistoryScans: 0 }; }
async function rebuildAggregate({ repositories, scope, updatedAt }) { for (const store of ['socialPersonas', 'socialGraphEdges', 'socialPosts', 'socialPostRecipients', 'socialComments', 'socialEngagements', 'socialDecisions']) for (const row of await repositories[store].list()) await repositories[store].delete(row.id); const sourceRows = await repositories.projections.listByIndex('by_scope_projector', [scope.storyId, scope.branchId, SOCIAL_PROJECTOR_ID]); let sourceRowsRead = 0; let rowsWritten = 0; for (const key of new Set(sourceRows.map(row => row.groupKey).filter(Boolean))) { const result = await materialize(repositories, scope, key, updatedAt); sourceRowsRead += result.sourceRowsRead; rowsWritten += result.rowsWritten; } return { sourceRowsRead, rowsWritten }; }
export function createSocialProjector() { return defineProjector({ id: SOCIAL_PROJECTOR_ID, version: 1, stores: ['socialPersonas', 'socialGraphEdges', 'socialPosts', 'socialPostRecipients', 'socialComments', 'socialEngagements', 'socialDecisions'], project, applyAggregate, rebuildAggregate }); }
